<?php
$caseAffiliations=$conn->query("SELECT id,name FROM ip_affiliations WHERE status='active' ORDER BY name")->fetch_all(MYSQLI_ASSOC);
$scope=current_user_tribe($conn);$scopeSql=$scope!==null?" WHERE tribe='".$conn->real_escape_string($scope)."'":'';
$caseRegistry=$conn->query("SELECT id,full_name FROM ip_records$scopeSql ORDER BY full_name LIMIT 500")->fetch_all(MYSQLI_ASSOC);
$memberSql="SELECT m.id,CONCAT_WS(' ',m.first_name,m.middle_name,m.last_name,m.suffix) full_name FROM ip_family_members m JOIN ip_families f ON f.id=m.family_id".($scope!==null?" WHERE f.owning_tribe='".$conn->real_escape_string($scope)."'":'')." ORDER BY full_name LIMIT 500";
$caseMembers=$conn->query($memberSql)->fetch_all(MYSQLI_ASSOC);$existingParticipants=$persons??[];
?>
<script>
const caseAffiliations=<?=json_encode($caseAffiliations)?>,caseRegistry=<?=json_encode($caseRegistry)?>,caseMembers=<?=json_encode($caseMembers)?>,existingParticipants=<?=json_encode(array_values($existingParticipants))?>;
function options(items,value,label,selected){return '<option value="">Not linked</option>'+items.map(x=>`<option value="${x[value]}" ${String(x[value])===String(selected||'')?'selected':''}>${String(x[label]).replaceAll('&','&amp;').replaceAll('<','&lt;')}</option>`).join('')}
const ipGroup=document.querySelector('[name="applicant_ip_group"]');if(ipGroup){const holder=document.createElement('div');holder.className='col-md-4 mt-2';holder.innerHTML=`<label class="form-label">Applicant Affiliation</label><select name="applicant_affiliation_id" class="form-select">${options(caseAffiliations,'id','name',<?=json_encode($case['applicant_affiliation_id']??null)?>)}</select>`;ipGroup.closest('[class*="col-"]')?.after(holder);}
const province=document.querySelector('[name="incident_province"]');if(province){const holder=document.createElement('div');holder.className='col-12 mt-2';holder.innerHTML='<label class="form-label">Incident Location (as reported)</label><input class="form-control" name="incident_location_text" value="<?=e($case['incident_location_text']??'')?>" placeholder="Complete or free-form incident location">';province.closest('[class*="col-"]')?.after(holder);}
function enhancePersonRows(){document.querySelectorAll('input[name="person_name[]"]').forEach((input,index)=>{const row=input.closest('.row');if(!row||row.dataset.enhanced)return;row.dataset.enhanced='1';row.classList.add('person-row','border','rounded','p-2','position-relative');const p=existingParticipants[index]||{};const role=row.querySelector('[name="person_role[]"]');if(role&&!role.querySelector('[value="representative"]'))role.insertAdjacentHTML('beforeend','<option value="representative">Representative</option>');if(role&&p.role)role.value=p.role.toLowerCase();row.insertAdjacentHTML('beforeend',`<div class="col-md-3"><label class="form-label small">Affiliation</label><select name="person_affiliation_id[]" class="form-select">${options(caseAffiliations,'id','name',p.affiliation_id)}</select></div><div class="col-md-3"><label class="form-label small">Legacy IP record</label><select name="person_ip_record_id[]" class="form-select">${options(caseRegistry,'id','full_name',p.ip_record_id)}</select></div><div class="col-md-4"><label class="form-label small">Family member</label><select name="person_family_member_id[]" class="form-select">${options(caseMembers,'id','full_name',p.family_member_id)}</select></div><div class="col-md-2"><label class="form-label small">Relationship</label><input name="person_relationship[]" class="form-control" value="${String(p.relationship_to_applicant||'').replaceAll('&','&amp;').replaceAll('"','&quot;')}"></div><div class="col-12 text-end"><button type="button" class="btn btn-sm btn-outline-danger" onclick="this.closest('.person-row').remove()"><i class="bi bi-trash"></i> Remove</button></div>`);});}
enhancePersonRows();const oldAdd=window.addPersonRow;window.addPersonRow=function(){if(oldAdd)oldAdd();enhancePersonRows();};
</script>
